<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import PartFeeExecutionPanel from './PartFeeExecutionPanel.vue'
import {FeeExecutionWork,type FeeExecutionOperation} from './fee-execution-work'
import type {FeeExecutionContext,FeeExecutionOwner,FeeExecutionTransport} from './fee-execution-client'
const props=defineProps<{context:FeeExecutionContext;owner:FeeExecutionOwner|null;transport:FeeExecutionTransport}>()
const amounts=ref<Record<string,string>>({}),records=ref<Record<string,string>>({}),tick=ref(0),partActive=ref(false)
const work=new FeeExecutionWork(props.transport,()=>props.owner,()=>crypto.randomUUID(),()=>tick.value++)
const operation=computed<FeeExecutionOperation|null>(()=>{tick.value;return work.operation}),projection=computed(()=>{tick.value;return work.projection}),busy=computed(()=>{tick.value;return work.busy}),projectionBusy=computed(()=>{tick.value;return work.projectionBusy}),message=computed(()=>{tick.value;return work.message}),projectionMessage=computed(()=>{tick.value;return work.projectionMessage})
const binding=computed(()=>JSON.stringify([props.owner,props.context.ticketId,props.context.ticketVersion,props.context.roundId,props.context.assignmentId,props.context.groupId,props.context.completionId,props.context.generation]))
function bind(){amounts.value={};records.value={};work.bind(props.context);tick.value++;void work.loadProjection().finally(()=>tick.value++)}
watch(binding,bind,{immediate:true})
function start(id:string){void work.start(id,records.value[id]??'',amounts.value[id]??'').finally(()=>tick.value++)}
function recover(query=true){void work.recover(query).finally(()=>tick.value++)}
function refreshProjection(){void work.loadProjection().finally(()=>tick.value++)}
function next(){work.next();tick.value++}
onBeforeUnmount(()=>work.dispose())
const cents=(v:string)=>(BigInt(v)/100n).toString()+'.'+(BigInt(v)%100n).toString().padStart(2,'0')
</script>
<template><section class="panel" data-testid="fee-execution-page"><h1>收费执行（LABOR / OTHER / PART事实）</h1><p>金额、数量、余额、owner状态和终态只展示服务端权威投影。执行成功不表示已收款。</p><p>工单 {{ context.ticketId }} · 轮次 {{ context.roundId }} · 当前分派 {{ context.assignmentId }} · 工单版本 {{ context.ticketVersion }}</p><p v-if="!owner" role="alert">当前身份、能力或企业范围尚未核实，执行入口关闭。</p><p v-if="projectionBusy">正在读取服务端权威收费执行事实…</p><p v-if="projectionMessage" role="alert">{{ projectionMessage }}</p><el-button :disabled="projectionBusy||!owner" @click="refreshProjection">重新读取权威投影</el-button><section v-if="projection" class="notice" data-testid="fee-execution-projection"><h2>服务端权威执行汇总</h2><p>factVersion：{{ projection.factVersion }} · 审批终态：{{ projection.completionState }} · 当前执行终态：{{ projection.executionState }}</p><p>批准金额 {{ cents(projection.approvedAmountCents) }} · 已执行金额 {{ cents(projection.executedAmountCents) }} · 真实剩余金额 {{ cents(projection.remainingAmountCents) }}</p></section><p v-else role="status">尚无完整权威投影，不显示余额，也不开放执行成功入口。</p><p v-if="message" role="status">{{ message }}</p><section v-if="operation" class="notice"><h2>原操作结果</h2><p>UUID：{{ operation.key }} · {{ operation.state }}</p><p>原批准行 {{ operation.body.lineId }} · 原处理记录 {{ operation.body.processingRecordId }} · 原金额 {{ cents(operation.body.amountCents) }}</p><el-button :disabled="busy" @click="recover(true)">只查询原UUID</el-button><el-button v-if="operation.state==='NOT_OBSERVED'" :disabled="busy||!projection" @click="recover(false)">显式同键同参数继续</el-button><el-button v-if="operation.state==='SUCCEEDED'" :disabled="busy" @click="next">重新读取后处理下一行</el-button></section><article v-for="line in projection?.lines ?? []" :key="line.lineId" class="record-entry"><h2>{{ line.kind }}</h2><p>批准行 {{ line.lineId }} · owner：{{ line.ownerSource }} · owner事实回执：{{ line.executionReceiptId }}</p><p>批准金额 {{ cents(line.approvedAmountCents) }} · 服务端已执行金额 {{ cents(line.executedAmountCents) }} · 真实剩余金额 {{ cents(line.remainingAmountCents) }}</p><p v-if="line.approvedQuantity!==undefined">批准数量 {{ line.approvedQuantity }} · 服务端已执行数量 {{ line.executedQuantity }} · 真实剩余数量 {{ line.remainingQuantity }}</p><p v-else>批准数量、已执行数量、剩余数量：该费用类型不适用数量。</p><p v-if="line.kind==='PART'" role="status">备件行通过下方入口核对原库存消耗并登记收费事实。</p><template v-else><label>真实处理记录<select v-model="records[line.lineId]" :disabled="!!operation||partActive||!owner||line.remainingAmountCents==='0'"><option value="">请选择</option><option v-for="record in context.records" :key="record.id" :value="record.id">{{ record.createdAt }} · {{ record.body }}</option></select></label><label>本次执行金额（分）<input v-model="amounts[line.lineId]" inputmode="numeric" :disabled="!!operation||partActive||!owner||line.remainingAmountCents==='0'"/></label><el-button :disabled="!!operation||partActive||busy||!owner||line.remainingAmountCents==='0'||!records[line.lineId]||!amounts[line.lineId]" @click="start(line.lineId)">提交收费执行</el-button></template></article><PartFeeExecutionPanel :context="context" :owner="owner" :transport="transport" :projection="projection" :blocked="!!operation||busy" @active="partActive=$event" @changed="refreshProjection"/></section></template>
